<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import InputError from '@/Components/InputError.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,router,useForm}from'@inertiajs/vue3';
const props=defineProps({payment:Object,invoices:Array});const verify=useForm({allocations:[{invoice_id:'',amount:props.payment.amount}]});const reject=useForm({notes:''});const refund=useForm({reason:''});const add=()=>verify.allocations.push({invoice_id:'',amount:''});
</script>
<template><Head :title="payment.payment_number"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="payments"/></template><div v-if="$page.props.flash.success" class="success-message mb-4">{{ $page.props.flash.success }}</div><div class="mb-6"><h1 class="text-3xl font-bold">{{ payment.payment_number }}</h1><p class="font-bold uppercase text-slate-500">{{ payment.status }}</p></div><div class="grid gap-6 lg:grid-cols-2"><section class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="mb-5 text-xl font-bold">Payment details</h2><dl class="grid grid-cols-2 gap-4"><div><dt class="text-xs uppercase text-slate-500">Customer</dt><dd class="font-bold">{{ payment.customer.name }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Amount</dt><dd class="font-bold">{{ payment.currency }} {{ payment.amount }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Method</dt><dd>{{ payment.payment_method }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Reference</dt><dd>{{ payment.transaction_reference }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Payment date</dt><dd>{{ payment.payment_date }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Provider</dt><dd>{{ payment.provider }}</dd></div></dl><a v-if="payment.proof_of_payment" :href="`/storage/${payment.proof_of_payment}`" target="_blank" rel="noopener" class="mt-5 inline-block font-bold text-cyan-700">View payment evidence</a><p v-if="payment.notes" class="mt-5 whitespace-pre-line">{{ payment.notes }}</p><div v-if="payment.verified_at" class="mt-5 rounded-xl bg-slate-50 p-4 text-sm">Finalized by {{ payment.verifier?.name }} at {{ payment.verified_at }}</div></section><section class="rounded-2xl bg-white p-6 shadow-sm"><template v-if="payment.status==='pending'"><h2 class="text-xl font-bold">Verify and allocate</h2><p class="mb-4 text-sm text-slate-500">The full payment must be allocated to eligible invoices.</p><form class="space-y-4" @submit.prevent="verify.post(route('admin.payments.verify',payment.uuid))"><div v-for="(allocation,index) in verify.allocations" :key="index" class="grid gap-3 rounded-xl border p-4 sm:grid-cols-2"><label>Invoice<select v-model="allocation.invoice_id" required><option value="">Select invoice</option><option v-for="invoice in invoices" :key="invoice.id" :value="invoice.id">{{ invoice.invoice_number }} — {{ invoice.currency }} {{ invoice.balance }} due</option></select><InputError :message="verify.errors[`allocations.${index}.invoice_id`]"/></label><label>Amount<input v-model="allocation.amount" type="number" min="0.01" step="0.01" required/><InputError :message="verify.errors[`allocations.${index}.amount`]"/></label></div><InputError :message="verify.errors.allocations"/><button type="button" class="form-secondary-button" @click="add">Split across another invoice</button><button class="form-button block" :disabled="verify.processing">Verify payment</button></form><form class="mt-8 border-t pt-6" @submit.prevent="reject.post(route('admin.payments.reject',payment.uuid))"><label>Rejection reason<textarea v-model="reject.notes" rows="3" required/></label><button class="mt-3 rounded-xl border border-red-200 px-5 py-3 font-bold text-red-700">Reject evidence</button></form></template><template v-else><h2 class="mb-4 text-xl font-bold">Allocations</h2><div v-for="allocation in payment.allocations" :key="allocation.uuid" class="flex justify-between border-b py-3"><span>{{ allocation.invoice.invoice_number }}</span><strong>{{ payment.currency }} {{ allocation.amount }}</strong></div><form v-if="payment.status==='verified'" class="mt-8 border-t pt-6" @submit.prevent="refund.post(route('admin.payments.refund',payment.uuid))"><label>Refund/reversal reason<textarea v-model="refund.reason" rows="3" required/></label><button class="mt-3 rounded-xl border border-red-200 px-5 py-3 font-bold text-red-700">Create refund record</button></form></template></section></div></PortalLayout></template>
